command:
$ErrorActionPreference='Stop'
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$candidate='b9e9bddcdcfa7ee7f9961bb16c0b003dce7d03cd'
$working=Join-Path $env:RUNNER_TEMP 'fly-indexed-extension-b9e9bddc'
if(Test-Path -LiteralPath $working){throw 'Unexpected candidate worktree path already exists'}
Set-Location -LiteralPath $repo
& git fetch origin feat/search-v3-indexed-extension --no-tags
if($LASTEXITCODE -ne 0){throw 'Candidate fetch failed'}
$observed=(& git rev-parse refs/remotes/origin/feat/search-v3-indexed-extension).Trim()
if($LASTEXITCODE -ne 0 -or $observed -ne $candidate){throw 'Candidate ref mismatch'}
try {
  & git worktree add --detach $working $candidate
  if($LASTEXITCODE -ne 0){throw 'Candidate worktree creation failed'}
  Set-Location -LiteralPath $working
  & python -X utf8 -m py_compile tests/winui/test_indexed_search_contract.py tests/winui/test_indexed_search_native.py tests/winui/test_indexed_search_gui.py
  if($LASTEXITCODE -ne 0){throw 'Indexed-search Python syntax failed'}
  & python -X utf8 -m unittest tests/winui/test_indexed_search_contract.py
  if($LASTEXITCODE -ne 0){throw 'Indexed-search source contracts failed'}
  & cmd.exe /c build.bat Release
  if($LASTEXITCODE -ne 0){throw 'Release build failed'}
  & python -X utf8 tests/winui/m19/test_native.py --configuration Release
  if($LASTEXITCODE -ne 0){throw 'M19 native regression failed'}
  & python -X utf8 tests/winui/test_indexed_search_native.py --configuration Release
  if($LASTEXITCODE -ne 0){throw 'Indexed-search SystemIndex oracle failed'}
  & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture after
  if($LASTEXITCODE -ne 0){throw 'Indexed-search owned GUI failed'}
  Write-Host 'INDEXED_EXTENSION_FOCUSED_ACCEPTANCE=PASS'
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $working){
    & git worktree remove --force $working
    if($LASTEXITCODE -ne 0){Write-Host 'CANDIDATE_WORKTREE_CLEANUP=FAILED'}
  }
  & git worktree prune
}
